export const PUSH = ["chest", "shoulders", "triceps"];
export const LOWER = ["abductors", "adductors", "calves", "glutes", "hamstrings", "quadriceps"];

export function canonical(name: string): string | null {
  const n = name.trim().toLowerCase().replace(/\s+/g, " ");
  const c = ALIASES[n] ?? n;
  return c in EXERCISES ? c : null;
}

export function bucket(m: string): string {
  return BUCKET[m] ?? m;
}

/** [muscle, weight] pairs; primary 1.0, secondary 0.5. Empty if unmapped. */
export function musclesFor(name: string): [string, number][] {
  const c = canonical(name);
  if (!c) return [];
  const [prim, sec] = EXERCISES[c];
  return [
    ...prim.map((m) => [m, 1.0] as [string, number]),
    ...sec.map((m) => [m, 0.5] as [string, number]),
  ];
}
